import{z as o,x as s,o as e,c as i,q as A,j as B,D as a,d as l,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Agent 循环的设计空间","description":"","frontmatter":{"title":"Agent 循环的设计空间","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-loop-design-space.md","filePath":"llm/agent-loop-design-space.md","lastUpdated":1791063341000}'),C={name:"llm/agent-loop-design-space.md"};function d(m,E,g,h,p,F){const t=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=A('<h1 id="agent-循环的设计空间" tabindex="-1">Agent 循环的设计空间 <a class="header-anchor" href="#agent-循环的设计空间" aria-label="Permalink to &quot;Agent 循环的设计空间&quot;">​</a></h1><div class="epigraph"><p>循环本身不是产品；循环上每个可调的点——谁决定下一步、何时停、观察走哪条通道——加起来才是。</p><footer>—— 据 Yao et al., ReAct, ICLR 2023；Wang 等，大模型自主代理综述，2024 整理</footer></div><p><a href="/llm/xai-map">上一课</a>把可解释性应用收成五步决策单与三条不变量：干预优先于相关、读数不是判决、口径绑定一切。解释了模型单步为什么这么走，下一个对象是模型自己连走多步——代理轨迹。它的缺口不在看得见与否：轨迹里每个 token 由谁追加，是模型在每一步决定的。主干已有 <a href="/llm/react">ReAct</a> 的推理—行动交错协议与 <a href="/llm/agent-harness-design">Agent Harness 设计</a> 的环外机制清单；本课把两者之间的自由度排成几根轴，作为本课程的地图，后课逐轴下钻。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最朴素的实现是一句 <code>while</code>：把任务与观察拼进上下文，调一次模型，执行它要的工具，把结果追加回去，直到它不再要工具。这层循环把三件必须显式决定的事都隐掉了。一是控制流：<span class="marginnote">术语翻译：控制流就是「谁在决定下一步做什么」。反应式是模型看着现场临时决定；先规划后执行是先写好路线图、照着走但可以改；状态机是按预先画好的流程图走，每一步只许做流程图上列的动作。</span>每一步是「看现状选动作」的反应式决策，还是先产出可修订的全局计划再执行——<a href="/llm/plan-vs-react">规划 vs 反应式循环</a>给过取舍，这里要问的是给模型多大自由度。二是停止：模型声明完成、预算耗尽、外部门禁否决，三种停法语义不同，混成一个 <code>finished</code>，评测与运维都读不出区别。三是观察通道：工具结果全文回填还是截断落盘，直接决定轨迹形状。三处都不设计的代价，<a href="/llm/autogpt-arch">AutoGPT 架构笔记</a>一类的早期自由循环已经演示过：目标漂移、空转、烧预算。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把设计空间立成五根轴。<strong>控制流</strong>：反应式（ReAct：思考对观察条件化）、先规划后执行（计划可被中途修订）、显式状态机或工作流图（每步合法动作集被收窄）。经验方向是反直觉的：模型越弱，越要收窄动作集；模型越强，越可以放宽控制流，但把省下的自由度换成更严的门禁。<strong>停止</strong>：finish 动作、步数与 token 预算、验证器判定分开记账，各自给出独立的结束原因。<strong>观察</strong>：回填规则决定上下文账本，本课只立「结果可追责」的契约，策略留给<a href="/llm/agent-context-strategies">上下文管理策略</a>。<strong>状态与记忆</strong>：放上下文里还是外部存储，留给<a href="/llm/agent-memory-implementation">记忆系统的实现</a>。<strong>人与权限</strong>：哪几类动作前必须人点头，留给<a href="/llm/agent-guardrails">安全围栏</a>。</p>',7)),(e(),B(r,null,{default:a(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20TASK%5B%22%E4%BB%BB%E5%8A%A1%E4%B8%8E%E7%B3%BB%E7%BB%9F%E6%8F%90%E7%A4%BA%22%5D%20--%3E%20ACT%5B%22%E6%A8%A1%E5%9E%8B%E9%80%89%E6%8B%A9%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20ACT%20--%3E%20EXEC%5B%22%E5%AE%BF%E4%B8%BB%E6%89%A7%E8%A1%8C%E5%B7%A5%E5%85%B7%22%5D%0A%20%20EXEC%20--%3E%20OBS%5B%22%E8%A7%82%E5%AF%9F%E5%9B%9E%E5%A1%AB%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20OBS%20--%3E%20GATE%7B%22%E9%A2%84%E7%AE%97%E6%88%96%E9%97%A8%E7%A6%81%E8%A7%A6%E5%8F%91%3F%22%7D%0A%20%20GATE%20--%3E%7C%22%E5%90%A6%22%7C%20ACT%0A%20%20GATE%20--%3E%7C%22%E6%98%AF%22%7C%20FIN%5B%22%E7%BB%93%E6%9D%9F%EF%BC%9A%E5%88%86%E8%AE%B0%E7%BB%93%E6%9D%9F%E8%AF%AD%E4%B9%89%22%5D%0A%20%20ACT%20--%3E%7C%22%E5%A3%B0%E6%98%8E%E5%AE%8C%E6%88%90%22%7C%20VER%5B%22%E9%AA%8C%E8%AF%81%E5%99%A8%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20VER%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20FIN%0A%20%20VER%20--%3E%7C%22%E4%B8%8D%E9%80%9A%E8%BF%87%22%7C%20OBS%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把循环读成马尔可夫链：状态是当前上下文，转移核是「模型选动作 × 工具给观察」。同一模型装进不同转移核，得到的是不同策略——这正是同一骨干换 harness 名次会掉的机制解释：改的不是模型，是策略所在的转移结构。<span class="marginnote">直觉类比：同一个棋手，下象棋、下围棋、下跳棋，水平发挥完全不同——棋手（模型）没变，变的是棋盘规则（转移核）。所以「换个框架分数就掉」不代表模型变笨，只说明它在新的规则下策略不同了。</span>设计选择因此不是品味，而是给转移核的约束强度定价：收窄动作集降低了走错步的概率，也封死了模型用非常规路径解决问题的可能。METR 把自主长度度量成时间视界：50% 完成视界约每七个月翻倍（<a href="/llm/metr-time-horizon">METR Time Horizon</a>），工程含义是预算阈值要随视界重设，不是一次设死。<span class="marginnote">数字实例：「50% 视界每七个月翻倍」的意思是：代理能稳定完成的任务时长每隔约七个月乘以 2。今天它能稳定跑完 30 分钟的任务，照这个速度约七个月后是 1 小时，再七个月后是 2 小时——所以半年前设的「最多 50 步」预算，今天多半已经过紧。</span>评测协议也要按这个语义记账（<a href="/llm/agent-eval-protocol">智能体与工具评测协议</a>），否则「失败」本身没有定义。</p><p><span class="marginnote">把结束原因分记为「模型声明完成」「预算耗尽」「门禁否决」三类，是循环设计里最便宜也最常被省掉的一件事。混报的代价：长任务成功率看似暴跌，实际大量轨迹死在预算上——那是预算语义错误，不是能力缺陷。</span></p>',3)),(e(),B(r,null,{default:a(()=>[n(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20K1%5B%22%E6%A0%B8%201%EF%BC%9A%E5%8F%8D%E5%BA%94%E5%BC%8F%3Cbr%2F%3E%E6%AF%8F%E6%AD%A5%E7%9C%8B%E7%8E%B0%E5%9C%BA%E9%80%89%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20M%20--%3E%20K2%5B%22%E6%A0%B8%202%EF%BC%9A%E5%85%88%E8%A7%84%E5%88%92%E5%90%8E%E6%89%A7%E8%A1%8C%3Cbr%2F%3E%E8%AE%A1%E5%88%92%E5%8F%AF%E4%B8%AD%E9%80%94%E4%BF%AE%E8%AE%A2%22%5D%0A%20%20M%20--%3E%20K3%5B%22%E6%A0%B8%203%EF%BC%9A%E7%8A%B6%E6%80%81%E6%9C%BA%20%2F%20%E5%B7%A5%E4%BD%9C%E6%B5%81%E5%9B%BE%3Cbr%2F%3E%E6%AF%8F%E6%AD%A5%E5%8A%A8%E4%BD%9C%E9%9B%86%E8%A2%AB%E6%94%B6%E7%AA%84%22%5D%0A%20%20K1%20--%3E%20P1%5B%22%E7%AD%96%E7%95%A5%201%EF%BC%9A%E7%81%B5%E6%B4%BB%EF%BC%8C%E6%98%93%E6%BC%82%E7%A7%BB%22%5D%0A%20%20K2%20--%3E%20P2%5B%22%E7%AD%96%E7%95%A5%202%EF%BC%9A%E6%9C%89%E5%85%A8%E5%B1%80%E6%96%B9%E5%90%91%EF%BC%8C%E8%AE%A1%E5%88%92%E5%8F%AF%E8%83%BD%E8%BF%87%E6%97%B6%22%5D%0A%20%20K3%20--%3E%20P3%5B%22%E7%AD%96%E7%95%A5%203%EF%BC%9A%E7%A8%B3%EF%BC%8C%E4%BD%86%E9%9D%9E%E5%B8%B8%E8%A7%84%E8%B7%AF%E5%BE%84%E8%A2%AB%E5%B0%81%E6%AD%BB%22%5D%0A%20%20P1%20--%3E%20Q%5B%22%E5%90%8C%E4%B8%80%E9%AA%A8%E5%B9%B2%EF%BC%8C%E6%8D%A2%20harness%20%E5%B0%B1%E6%98%AF%E6%8D%A2%E7%AD%96%E7%95%A5%3Cbr%2F%3E%E5%90%8D%E6%AC%A1%E5%8F%98%E5%8C%96%E6%98%AF%E6%9C%BA%E5%88%B6%E5%B7%AE%E5%BC%82%EF%BC%8C%E4%B8%8D%E6%98%AF%E7%8E%84%E5%AD%A6%22%5D%0A%20%20P2%20--%3E%20Q%0A%20%20P3%20--%3E%20Q%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课立轴，不替后课做决定：观察回填的策略、记忆的分层、权限的卡点各有专课；多代理分叉（编排者—工人、辩论）留给<a href="/llm/agent-multi-orchestration">多 Agent 编排模式</a>。单步动作如何进协议是下一课。训练侧如何把这条循环搬进 RL 环境（<a href="/llm/tool-integrated-rl">工具整合推理 RL</a>、<a href="/llm/agent-lightning">Agent Lightning</a>）是另一条课程：环内行为可被训练，但部署时的转移核若与训练分布不同构，分数会掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>循环有五根轴：控制流、停止语义、观察通道、状态位置、人的卡点；本课程逐轴展开。</li><li>结束原因必须三分：模型声明、预算耗尽、门禁否决；混报让评测与运维同时失明。</li><li>模型弱则收窄动作集，模型强则放宽控制流、加严门禁。</li><li>同一模型换转移核就是换策略；harness 差异是机制差异，不是玄学。</li><li>预算阈值按时间视界重设，不一次设死。</li><li>出处：据 Yao et al., ReAct, ICLR 2023 与 Wang 等自主代理综述（2024）的循环口径整理；时间视界数字见 METR 2025 技术报告。</li></ul>',4))])}const _=o(C,[["render",d]]);export{c as __pageData,_ as default};
